function Logo({ animated, style }: { animated: boolean; style: boolean }) {
  return (
    <div className="logo-container">
      <img
        fetchPriority="high"
        alt="TryDos Logo"
        width={130}
        height={36}
        loading="eager"
        src="/svg/Logo.svg"
      />
    </div>
  );
}

export default Logo;

import { configureStory } from "utils/functions";
import { getUserStories } from "utils/functions";
import { v4 as uuidv4 } from "uuid";
const initialState = {
  language: "en",
  loading: false,
  loadingStories: true,
  selectedStory: null,
  renderStories: false,
  storiesData: null,
  categories: [],

  settings: null,
  loginOpen: false,
  boutiques: [],
  categories: [],
  session_id: uuidv4(),
  previous_event_button_name: null,
  activeRoute: "/",
  showMessage: false,
  currency: null,
  countries: [],
  isRegisteringReady: true,
};

const HomeReducer = (state = initialState, { type, payload }) => {
  switch (type) {
    case "IS-REGISTERING": {
      return {
        ...state,
        isRegisteringReady: payload,
      };
    }
    case "COUNTRIES-DATA": {
      return {
        ...state,
        countries: payload,
      };
    }
    case "CURRENCY": {
      return {
        ...state,
        currency: payload,
      };
    }
    case "ACTIVE-ROUTE": {
      return {
        ...state,
        activeRoute: payload,
      };
    }
    case "LOADING": {
      return {
        ...state,
        loading: true,
      };
    }
    case "GA-EVENT": {
      return {
        ...state,
        previous_event_button_name: payload,
      };
    }
    case "LOGIN-OPEN": {
      if (payload) {
        document.documentElement.style.overflow = "hidden";
      } else {
        document.documentElement.style.overflow = "initial";
      }
      return {
        ...state,
        loginOpen: payload,
        showMessage: false,
      };
    }
    case "INFO_EXPIRED_TOKEN": {
      return {
        ...state,
        showMessage: payload,
      };
    }
    case "WATCH-STORY": {
      let arr = [];
      state.storiesData.map((story) => {
        if (story.id === payload.id) {
          let arrStories = [];
          story.stories.map((storyItem) => {
            if (storyItem.id === payload.pid) {
              arrStories.push({ ...storyItem, is_seen: true });
            } else {
              arrStories.push(storyItem);
            }
          });
          arr.push({ ...story, stories: arrStories });
        } else {
          arr.push(story);
        }
      });
      return {
        ...state,
        storiesData: arr,
      };
    }
    case "APP-LANGUAGE": {
      return { ...state, language: payload };
    }
    case "STORY-SELECTED": {
      return {
        ...state,
        selectedStory: payload,
        renderStories: !state.renderStories,
      };
    }
    case "STORY-DATA": {
      return { ...state, storiesData: payload, loadingStories: false };
    }
    case "NEXT-STORY": {
      let index;
      state.storiesData.map((story, i) => {
        if (story.id === payload) index = i;
      });
      if (index < state.storiesData.length - 1)
        return {
          ...state,
          selectedStory: configureStory(
            state.storiesData.filter((story, i) => i === index + 1)[0]
          ),
          renderStories: !state.renderStories,
        };
      else return { ...state, selectedStory: null };
    }
    case "PREV-STORY": {
      let index;
      state.storiesData.map((story, i) => {
        if (story.id === payload) index = i;
      });
      if (index > 0)
        return {
          ...state,
          selectedStory: configureStory(
            state.storiesData.filter((story, i) => i === index - 1)[0]
          ),
          renderStories: !state.renderStories,
        };
      else return { ...state, selectedStory: state.selectedStory };
    }
    case "ADD-STORY": {
      let arr = [];
      state.storiesData.map((storyItem) => {
        if (storyItem.id === payload.user_id) {
          arr.push({ ...storyItem, stories: [...storyItem.stories, payload] });
        } else {
          arr.push(storyItem);
        }
      });
      if (
        !state.storiesData.some(
          (user) => parseInt(user.id) === parseInt(payload.user_id)
        )
      ) {
        arr.push({ ...getUserStories(), stories: [payload] });
      }
      return {
        ...state,
        storiesData: [
          arr.filter((storyUser) => storyUser.id === payload.user_id)[0],
          ...arr.filter((storyUser) => storyUser.id !== payload.user_id),
        ],
      };
    }
    case "SITE-MAIN-DATA": {
      return {
        ...state,
        loading: false,
        boutiques: payload,
      };
    }
    case "GET_SETTINGS": {
      return {
        ...state,
        settings: payload.data,
      };
    }
    default:
      return state;
  }
};
export default HomeReducer;

const initialState = {
  products: [],
  loading: true,
  isReachEnd: false,
  offset: null,
  filterEnabled: false,
  skeleton: false,
  showedFilter: "Categories",
};

const ListingReducer = (state = initialState, { type, payload }) => {
  switch (type) {
    case "SHOWED-FILTER": {
      return { ...state, showedFilter: payload };
    }
    case "filterEnabled": {
      if (document.querySelector(".filter-container"))
        document.querySelector(".filter-container").scrollLeft = 0;
      return {
        ...state,
        filterEnabled: payload,
      };
    }
    case "GET_PRODUCT": {
      let arr = [];
      payload?.products?.map((s) => {
        arr.push({ ...s, id: s.product_id });
      });
      return {
        ...state,
        products: arr ?? [],
        offset: payload?.offset,
        limit: 4,
        loading: false,
        skeleton: false,
      };
    }
    case "Skeleton-Listing": {
      return {
        ...state,
        skeleton: true,
      };
    }
    case "PRODUCT_LOADING": {
      return {
        ...state,
        loading: true,
      };
    }
    case "GET_NEXT_PRODUCT": {
      let arr = [];
      payload?.products?.map((s) => {
        arr.push({ ...s, id: s.product_id });
      });
      return {
        ...state,
        products: [
          ...state.products,
          ...arr.filter(
            (s) => state.products.filter((d) => d.id === s.id).length === 0
          ),
        ],
        offset: payload.offset,
        isReachEnd: payload.products.length === 0,
        loading: false,
      };
    }
    case "GET_NEXT_PRODUCT_ERROR": {
      return {
        ...state,

        loading: false,
      };
    }
    case "RESET_LISTING_FILTER": {
      return {
        ...state,
        offset: 1,
        isReachEnd: false,
        loading: false,
      };
    }
    case "RESET-OFFSET": {
      return {
        ...state,
        offset: 1,
      };
    }
    default:
      return state;
  }
};
export default ListingReducer;

const initialState = {
  value: "",
  searchWords: [].sort(),
  totalProducts: null,
  searchResults: {
    products: [],
    brands: [],
    categories: [],
    boutiques: [],
  },
  enable: false,
  searchFilters: { categories: [], brands: [], boutiques: [] },
  loading: false,
  partialLoading: false,
};

const SearchReducer = (state = initialState, { type, payload }) => {
  switch (type) {
    case "SEARCH-PARTIAL-LOADING": {
      return {
        ...state,
        partialLoading: payload,
      };
    }
    case "SEARCH-CATEGORY": {
      return {
        ...state,
        searchFilters: {
          ...state.searchFilters,
          categories: state.searchFilters.categories.some(
            (s) => s.slug === payload.slug
          )
            ? [
                ...state.searchFilters.categories.filter(
                  (s) => payload.slug !== s.slug
                ),
              ]
            : [...state.searchFilters.categories, payload],
        },
      };
    }
    case "SEARCH-BRAND": {
      return {
        ...state,
        searchFilters: {
          ...state.searchFilters,
          brands: state.searchFilters.brands.some(
            (s) => s.slug === payload.slug
          )
            ? [
                ...state.searchFilters.brands.filter(
                  (s) => payload.slug !== s.slug
                ),
              ]
            : [...state.searchFilters.brands, payload],
        },
      };
    }
    case "SEARCH-BOUTIQUE": {
      return {
        ...state,
        searchFilters: {
          ...state.searchFilters,
          boutiques: state.searchFilters.boutiques.some(
            (s) => s.slug === payload.slug
          )
            ? [
                ...state.searchFilters.boutiques.filter(
                  (s) => payload.slug !== s.slug
                ),
              ]
            : [...state.searchFilters.boutiques, payload],
        },
      };
    }
    case "SEARCH-RESULTS": {
      return {
        ...state,
        searchResults: {
          ...state.searchResults,
          ...payload,
        },
      };
    }
    case "FIND-PRODUCTS": {
      return {
        ...state,
        searchResults: {
          ...state.searchResults,
          products: payload,
        },
        searchWords: payload.map((s) => s.name),
        loading: false,
      };
    }
    case "SEARCH-LOADING": {
      return { ...state, loading: true };
    }
    case "SEARCH-WORD": {
      return {
        ...state,
        value: payload,
      };
    }
    case "ENABLE-SEARCH": {
      if (payload)
        return {
          ...state,
          enable: payload,
        };
      else
        return {
          ...state,
          value: "",
          searchFilters: {
            categories: [],
            brands: [],
            boutiques: [],
          },
          enable: false,
          totalProducts: null,
        };
    }
    case "RESET-SEARCH-FILTER": {
      return {
        ...state,
        searchFilters: {
          categories: [],
          brands: [],
          boutiques: [],
        },
        totalProducts: null,
      };
    }
    case "EDIT-FILTER-SEARCH": {
      return {
        ...state,
        loading: false,
        searchResults: {
          ...state.searchResults,
          ...payload,
        },
        totalProducts: payload.total_size,
      };
    }
    default:
      return state;
  }
};
export default SearchReducer;

const initialState = {
  user: null,
  Tempuser: null,
  failedLogin: false,
  attempts: 4,
  wrongNumber: "",
  loading: false,
  verficationID: null,
  firebaseSettings: {}
};

const AuthReducer = (state = initialState, { type, payload }) => {
  switch (type) {
    case "CANCEL-AUTH": {
      return {
        ...state,
        user: null,
        Tempuser: null,
        failedLogin: false,
        attempts: 4,
        wrongNumber: "",
        loading: false,
        verficationID: null,
      };
    }
    case "LOGIN_SUCCESS":
      return {
        ...state,
        user: state.user ? { ...state.user, ...payload } : payload,
        Tempuser: state.user ? { ...state.user, ...payload } : payload,
        failedLogin: false,
      };
    case "LOGIN_FAILED": {
      return { ...state, failedLogin: true, attempts: state.attempts - 1 };
    }
    case "RE-INITILIASE": {
      return { ...state, failedLogin: false, wrongNumber: "" };
    }
    case "WRONG-NUMBER": {
      return { ...state, wrongNumber: payload };
    }
    case "LOADING-OTP": {
      return {
        ...state,
        loading: payload,
      };
    }
    case "SET-VERFICATION-ID": {
      return {
        ...state,
        verficationID: payload,
      };
    }
    // case "UPDATE_USER_INFO": {
    //   return {
    //     ...state,
    //     user: { ...payload, already_exists: state.user?.already_exists },
    //     Tempuser: { ...payload, already_exists: state.user?.already_exists },
    //   };
    // }
    case "GET_FIREBASE_SETTINGS": {
      return {
        ...state,
        firebaseSettings: payload
      };
    }
    case "TEMP-USER": {
      return {
        ...state,
        Tempuser: payload,
      };
    }
    case "UPDATE-NAME": {
      return {
        ...state,
        user: { ...state.user, name: payload },
        Tempuser: { ...state.user, name: payload },
      };
    }
    default:
      return state;
  }
};

export default AuthReducer;

"use client";

// eslint-disable-next-line no-restricted-imports
import Link from "next/link";
import React, { ComponentProps, MouseEventHandler, useEffect } from "react";
import { usePathname } from "next/navigation";

export interface INextLinkProps
  extends Omit<ComponentProps<typeof Link>, "href"> {
  href: string;
}
export default function NextLink({
  href,
  className,
  children,
  onClick,
  ...props
}: INextLinkProps) {
  const pathname = usePathname();

  const handleClick: MouseEventHandler<HTMLAnchorElement> = (e) => {
    onClick?.(e);
  };

  return (
    <Link
      prefetch={true}
      className={className}
      href={href}
      {...props}
      rel="prefetch"
      onClick={(e) => {
        onClick(e);
      }}
    >
      <>{children}</>
    </Link>
  );
}

"use client";
import NextLink from "components/global/NextLink";
import { useParams } from "next/navigation";
import { useEffect } from "react";
import { encode_utf8 } from "utils/functions";

function Boutique({ data }) {
  useEffect(() => {
    encode_utf8({
      element: document.querySelectorAll(
        `.boutique-desc-notification-${data.boutique_slug}`
      ),
      s: data.description,
    });
  }, []);
  const { lang } = useParams();
  return (
    <NextLink
      className="flex-col"
      href={`/${lang}/boutiques/${data.boutique_slug}`}
      prefetch
    >
      <div className="regular p-2">{data?.showed_type}</div>
      <div className="flex-row items-center">
        <div className="b-icon">
          {data.boutique_icon?.file_path && (
            <img width={20} height={20} src={data.boutique_icon?.file_path} />
          )}
        </div>
        <div
          className={`regular flex ml-2 boutique-desc-notification-${data.boutique_slug}`}
        ></div>
      </div>
    </NextLink>
  );
}

export default Boutique;

"use client";
import { useDispatch } from "react-redux/es";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
function ProductToOldCart({ data }) {
  const dispatch = useDispatch();
  const pathname = usePathname();
  const router = useRouter();
  const searchParams = useSearchParams();
  const openCart = () => {
    window.history.pushState({ isPopup: true }, "open Cart");
    dispatch({ type: "ENABLE-CART", payload: true });

    const newParams = new URLSearchParams(searchParams);
    newParams.set("cart", "true");

    // Use router.push with pathname and updated query
    // @ts-expect-error 'shallow' does not exist in type 'NavigateOptions'
    router.push(`${pathname}?${newParams.toString()}`, { shallow: true });
  };
  return (
    <div className="flex-col" onClick={() => openCart()}>
      <div className="regular p-2">{data.showed_type}</div>
      <div className="flex-row items-center">
        <div className="b-icon">
          <img width={20} height={20} src={"svg/CartIcon.svg"} />
        </div>
        <div className={`regular inline ml-2 boutique-desc-notification`}>
          {data.description}
        </div>
      </div>
    </div>
  );
}

export default ProductToOldCart;

import NextLink from "components/global/NextLink";

function Category({ data }) {
  return (
    <NextLink
      className="flex-col"
      href={`/boutiques/listing?categories=${data.category_slug}`}
      prefetch
    >
      <div className="regular p-2">{data?.showed_type}</div>
      <div className="flex-row items-center">
        <div className="b-icon">
          <img width={20} height={20} src={data.image} />
        </div>
        <div
          className={`regular flex ml-2 boutique-desc-notification-${data.category_slug}`}
        >
          {data.description}
        </div>
      </div>
    </NextLink>
  );
}

export default Category;

import NextLink from "components/global/NextLink";

function ProductAvailable({ data }) {
  return (
    <NextLink
      className="flex-row"
      href={`/products/${data.product_slug}`}
      prefetch
    >
      <div className="b-icon">
        <img width={80} height={"auto"} src={data.image} />
      </div>
      <div className="flex-col m-2">
        <div className="regular p-2">{data.description}</div>
      </div>
    </NextLink>
  );
}

export default ProductAvailable;

"use client";
import { store } from "store";
import { GetChats } from "store/chat/actions";
import Cookies from "js-cookie";
import userImage from "public/images/profileNo.png";
import {
  _isStoreLastJson,
  AddToCartAnimation,
  ExpiredUser,
  getCart,
  getOldCart,
  getLang,
  getUser,
  UserID,
  UserToken,
  WaitForCondition,
} from "utils/functions";
import Smartlook from "smartlook-client";

import {
  CUSTOMER_INFO_URL,
  FIREBASE_SETTINGS_URL,
  HOME_DATA_URL,
  LISTING_INFO_URL,
  REGISTER_DEVICE_URL,
  STARTER_SETTINGS,
} from "utils/endpointConfig";
import { SSRDetect } from "utils/functions";
import { GetMainData } from "store/homepage/actions";
import { toast } from "react-toastify";
import axios from "axios";
import {
  onMessageListener,
  requestFirebaseNotificationPermission,
} from "utils/firebaseInitv1";
import { AxiosGet, AxiosPost } from "utils/AxiosApi";
import { changeToken } from "store/homepage/cachedActions";
import {
  CustomerInfoApi,
  GetBoutiqueApi,
  GetProductApi,
  RegisterGuestApi,
  StarttingSettingApi,
  UpdateCartApi,
} from "models/Api";
const getHeader = () => {
  let [countryUrl, languageUrl] = window.location.pathname
    .split("/")[1]
    .split("-");
  return {
    next: {
      revalidate: parseInt(process.env.NEXT_PUBLIC_REVALIDATE),
    },
    headers: {
      Authorization: `Bearer ${
        localStorage.getItem("MARKET-TOKEN") ||
        localStorage.getItem("DEVICE-TOKEN")
      }`,
      lang: getLang(languageUrl, Cookies.get("language")),
      country: countryUrl || Cookies.get("country"),
      accept: "application/json",
    },
  };
};
class HomeService {
  async getClientData() {
    try {
      const response = await fetch(
        process.env.NEXT_PUBLIC_BACKEND_URL + STARTER_SETTINGS,
        getHeader()
      );
      let repo: { data: StarttingSettingApi } = await response.json();
      store.dispatch({ type: "GET_SETTINGS", payload: repo });
      sessionStorage.setItem("starttingSetting", JSON.stringify(repo.data));
      await this.getCustomerInfo();

      // const response2 = await AxiosGet({
      //   url: process.env.NEXT_PUBLIC_BACKEND_URL + FIREBASE_SETTINGS_URL,
      //   title: "get firebase settings request",
      // });
      // store.dispatch({
      //   type: "GET_FIREBASE_SETTINGS",
      //   payload: response2?.firebase_settings,
      // });
      getCart({
        callback: ([data, res]) => {
          store.dispatch({
            type: "CART-INIT",
            payload: data ?? { cart: [] },
          });
        },
      });
      await getOldCart();
      if (typeof window !== "undefined") {
        _isStoreLastJson() &&
          localStorage.setItem("LAST_JSON", JSON.stringify(repo));
      }
      setTimeout(() => {
        if (localStorage.getItem("USER")) GetChats(false);
      }, 5000);
    } catch (e) {
      console.error(e);
    }
  }
  async getCustomerInfo() {
    await WaitForCondition();
    const response = await fetch(
      process.env.NEXT_PUBLIC_BACKEND_URL + CUSTOMER_INFO_URL,
      getHeader()
    );
    if (response.status === 200) {
      let repo: {
        data: CustomerInfoApi;
      } = await response.json();

      if (repo.data) {
        store.dispatch({
          type: "UPDATE_USER_INFO",
          payload: repo.data?.customer_info,
        });
        // localStorage.setItem(
        //   "customer-info",
        //   JSON.stringify(repo.data.customer_info)
        // );
        if (typeof window !== "undefined") {
          _isStoreLastJson() &&
            localStorage.setItem("LAST_JSON", JSON.stringify(repo));
        }
      }
    }
    if (response.status === 500 || response.status === 422) {
      toast.error("Customer Info Error");
    }
    if (response.status === 302 || response.status === 401) {
      if (getUser()) {
        await ExpiredUser();
      } else {
        await this.registerForExpire();
        await this.getCustomerInfo();
      }
    }
  }
  async checkExpiration(bool) {
    if (localStorage.getItem("USER")) {
      if (bool) {
        store.dispatch({ type: "CANCEL-AUTH" });
        Cookies.remove("MARKET-TOKEN");
        localStorage.clear();
        store.dispatch({ type: "LOGIN-OPEN", payload: true });
      }
    } else if (localStorage.getItem("guest-user") || bool) {
      Cookies.remove("MARKET-TOKEN");
      // Split the date into day, month, year

      if (bool) {
        Cookies.remove("DEVICE-TOKEN");

        // localStorage.clear();
        setTimeout(async () => {
          await this.registerForExpire();
        }, 2000);
      }
    }
  }
  async registerForExpire(id?: number) {
    let isReady = store.getState().homepage.isRegisteringReady;
    if (isReady) {
      let body = id
        ? { old_guest_user_id: id }
        : localStorage.getItem("guest-user")
        ? {
            old_guest_user_id: JSON.parse(localStorage.getItem("guest-user"))
              .id,
          }
        : { old_guest_user_id: null };

      try {
        store.dispatch({ type: "IS-REGISTERING", payload: false });
        let response = await fetch(
          process.env.NEXT_PUBLIC_BACKEND_URL + REGISTER_DEVICE_URL,
          {
            method: "POST",
            body: body.old_guest_user_id
              ? new URLSearchParams({
                  old_guest_user_id: body.old_guest_user_id,
                })
              : "old_guset_user_id=null",
            ...getHeader(),
            cache: "no-cache",
          }
        );
        let repo: RegisterGuestApi = await response.json();
        changeToken({ key: "DEVICE-TOKEN", value: repo.data.token });
        localStorage.setItem("DEVICE-TOKEN", repo.data.token);
        Cookies.set("DEVICE-TOKEN", repo.data.token, {
          expires: 365,
        });
        localStorage.setItem(
          "guest-user",
          JSON.stringify({
            ...repo.data.user,
            expired_at: repo.data.expires_at,
          })
        );
        if (repo.data.user) {
          Smartlook.identify(repo.data.user.id, {
            name: repo.data.user.name,
            phone: "guest",
            // other custom properties
          });
        }
        store.dispatch({ type: "IS-REGISTERING", payload: true });
      } catch (error) {
        store.dispatch({ type: "IS-REGISTERING", payload: true });
      }
    }
  }
  async CheckLogin() {
    if (!localStorage.getItem("FB-DEVICE-TOKEN")) await this.RegisterDevice();
    if (
      SSRDetect() &&
      localStorage.getItem("USER") &&
      JSON.parse(localStorage.getItem("USER")).is_verified &&
      localStorage.getItem("ID-TOKEN") &&
      localStorage.getItem("MARKET-TOKEN")
    ) {
      Cookies.set("MARKET-TOKEN", localStorage.getItem("MARKET-TOKEN"));
      changeToken({
        key: "MARKET-TOKEN",
        value: localStorage.getItem("MARKET-TOKEN"),
      });

      Smartlook.identify(JSON.parse(localStorage.getItem("USER")).id, {
        name: JSON.parse(localStorage.getItem("USER")).name,
        phone: JSON.parse(localStorage.getItem("USER")).mobilePhone,
        // other custom properties
      });
      store.dispatch({
        type: "LOGIN_SUCCESS",
        payload: {
          id: JSON.parse(localStorage.getItem("USER")).id,
          idToken: localStorage.getItem("ID-TOKEN"),
