        if (a.id === ac) {
          let mar = [];
          let sele = a.messages;
          sele.map((m) => {
            if (
              m.mid &&
              m.mid === payload.mid &&
              mar.filter((S) => S.id === payload.id).length === 0
            ) {
              mar.push({
                ...payload,
                message_status: m.message_status,
                mid: null,
              });
            } else {
              mar.push(m);
            }
          });
          if (
            payload.recive &&
            payload.sender_user_id !== getUserChat()?.id &&
            mar.filter((S) => S.id === payload.id).length === 0
          ) {
            mar.push({ ...payload, mid: null });
          }
          chatData.push({ ...a, messages: [...mar] });
        } else {
          chatData.push(a);
        }
      });
      if (
        state.activeChat &&
        state.activeChat.id &&
        state.activeChat.id === ac
      ) {
        act = chatData.filter((a) => a.id === ac)[0];
      } else {
        if (state.activeChat && state.activeChat.id) {
          act = state.activeChat;
        }
      }
      let arr = [];
      chatData.map((a) => {
        if (a.id === ac) {
          arr.push(a);
        }
      });
      chatData.map((a) => {
        if (a.id !== ac) {
          arr.push(a);
        }
      });
      let news = [];
      if (
        payload.recive &&
        state.activeChat &&
        state.activeChat &&
        payload.cid !== state.activeChat.id
      ) {
        if (state.newChats.filter((a) => a.id === payload.cid).length === 0)
          news = [
            ...state.newChats,
            state.data.filter((f) => f.id === payload.cid)[0],
          ];
        else if (!state.activeChat && !state.activeChat.id && payload.recive)
          news = [
            ...state.newChats,
            state.data.filter((f) => f.id === payload.cid)[0],
          ];
      }
      if (state.activeChat && state.activeChat.id) {
      } else {
        news = [
          ...state.newChats,
          state.data.filter((f) => f.id === payload.cid)[0],
        ];
      }

      return {
        ...state,
        data: [...arr],
        activeChat: act ? { ...act } : null,
        newChats: [...news],
        ref: !state.ref,
        refs: !state.refs,
      };
    }
    case "MAIN": {
      return {
        ...state,
        main: payload,
      };
    }
    case "SHOW-MODAL": {
      return {
        ...state,
        nameModal: payload,
      };
    }
    case "STORE_TOKEN_RED": {
      return {
        ...state,
        fbToken: payload,
      };
    }
    case "GET_CHAT_RED": {
      let arr = [];
      let chatData = [];
      let users = [];
      let prr = [];
      payload.map((a) => {
        let unique = a.channel_members.filter(
          (df) => df.user_id !== getUserChat()?.id
        )[0];
        users.push(unique.user_id);
        chatData.push({ ...a, messages: a.messages.reverse() });
      });
      let temp = state.activeChat;
      if (
        state.activeChat &&
        state.activeChat.id &&
        payload.filter((a) => a.id === state.activeChat.id).length > 0
      ) {
        temp = payload.filter((a) => a.id === state.activeChat.id)[0];
      }
      if (state.data.length !== payload.length) {
        payload.map((adsd) => {
          if (state.data.filter((ch) => ch.id === adsd.id).length === 0) {
            if (
              adsd.messages.filter(
                (mes) =>
                  mes.message_status.filter(
                    (st) => st.user_id === getUserChat()?.id
                  )[0]?.is_watched === false
              ).length > 0
            )
              arr.push(adsd);
          }
        });
      }
      param.map((p) => {
        prr.push({ ...p, messages: p.messages.reverse() });
      });
      return {
        ...state,
        data: [...prr, ...chatData],
        activeChat: temp?.id ? { ...temp } : null,
        newChats: arr,
        chatUsers: users,
        loading: true,
      };
    }
    case "CHAT_LOADING": {
      return {
        ...state,
        loading: true,
      };
    }
    case "CHAT_DONE": {
      return {
        ...state,
        loading: false,
      };
    }
    case "DEL_CHAT": {
      return {
        ...state,
        data: state.data.filter((a) => a.id !== payload),
      };
    }
    case "qouted": {
      return {
        ...state,
        qouted: payload,
      };
    }
    case "GRP": {
      let arr = [];
      let active = state.activeChat;

      state.data.map((ch) => {
        if (parseInt(ch.id) === parseInt(payload.ch)) {
          let mrr = [];
          payload.mes.map((m) => {
            if (mrr.filter((s) => s.id === m.id).length === 0) {
              mrr = [m, ...mrr];
            }
          });
          ch.messages.map((m) => {
            if (mrr.filter((s) => s.id === m.id).length === 0) {
              mrr.push(m);
            }
          });
          arr.push({ ...ch, messages: mrr });
        } else {
          arr.push(ch);
        }
      });
      return {
        ...state,
        data: arr,
        activeChat: arr.filter(
          (s) => parseInt(s.id) === parseInt(state.activeChat.id)
        )[0],
        fetch: true,
        search: {
          ...state.search,
          loading: false,
        },
        first: false,
        mid: payload.mes.length === 0 ? null : state.mid,
      };
    }

    case "GET_CHAT_PAGE": {
      return {
        ...state,
        fetch: false,
        mid: payload,
      };
    }
    case "MUTE_CHAT_REDUCER": {
      if (!payload.event) {
        MuteChat(payload);
      }
      let arr = [];
      state.data.map((chat) => {
        if (chat.id === payload.id) {
          arr.push({
            ...state.data.filter((s) => s.id === payload.id)[0],
            channel_members: [
              state.data
                .filter((s) => s.id === payload.id)[0]
                ?.channel_members.filter(
                  (mem) => mem.user_id !== getUserChat()?.id
                )[0],
              {
                ...state.data
                  .filter((s) => s.id === payload.id)[0]
                  ?.channel_members.filter(
                    (mem) => mem.user_id === getUserChat()?.id
                  )[0],
                mute: payload.value ? 1 : 0,
              },
            ],
          });
        } else {
          arr.push(chat);
        }
      });

      return {
        ...state,
        data: arr,
      };
    }
    case "PIN_CHAT_REDUCER": {
      if (state.pinnedChats.length < 3) {
        if (!payload.event) {
          PinnChat(payload);
        }
        let arr = [];
        arr = [
          ...state.data.filter((s) => s.id !== payload.id),
          {
            ...state.data.filter((s) => s.id === payload.id)[0],
            channel_members: [
              state.data
                .filter((s) => s.id === payload.id)[0]
                ?.channel_members.filter(
                  (mem) => mem.user_id !== getUserChat()?.id
                )[0],
              {
                ...state.data
                  .filter((s) => s.id === payload.id)[0]
                  ?.channel_members.filter(
                    (mem) => mem.user_id === getUserChat()?.id
                  )[0],
                pin: payload.value ? 1 : 0,
              },
            ],
          },
        ];
        return {
          ...state,
          data: arr,
        };
      } else {
        Toast();
        return {
          ...state,
        };
      }
    }
    case "UNREAD_CHAT_REDUCER": {
      let arr = [];
      state.data.map((chat) => {
        if (chat.id === payload.id) {
          arr.push({ ...chat, unread: payload.value });
        } else arr.push(chat);
      });
      return {
        ...state,
        data: arr,
      };
    }
    case "EDIT_CHAT_INFO": {
      let arr = [];
      let active = state.activeChat;
      state.data.map((s) => {
        if (parseInt(s.id) === parseInt(payload.id)) {
          arr.push({ ...s, message_counts: payload.data });
        } else {
          arr.push(s);
        }
      });
      if (active && parseInt(active?.id) === parseInt(payload.id)) {
        active = { ...active, message_counts: payload.data };
      }
      return { ...state, data: arr, activeChat: active };
    }
    case "EDIT_CHAT_INFO_MEDIA": {
      let arr = [];
      let active = state.activeChat;
      state.data.map((s) => {
        if (parseInt(s.id) === parseInt(payload.id)) {
          arr.push({
            ...s,
            message_counts: {
              ...s.message_counts,
              ...getMediaReducer(media, payload.data),
            },
          });
        } else {
          arr.push(s);
        }
      });
      if (active && parseInt(active?.id) === parseInt(payload.id)) {
        active = {
          ...active,
          message_counts: {
            ...s.message_counts,
            ...getMediaReducer(media, payload.data),
          },
        };
      }
      return { ...state, data: arr, activeChat: active };
    }
    case "DELETE_CHAT_REDUCER": {
      deleteChat(payload.id);
      return {
        ...state,
        data: state.data.filter(
          (chat) => parseInt(chat.id) !== parseInt(payload.id)
        ),
        activeChat: null,
        main: "main",
      };
    }
    case "DELETE_MESSAGE": {
      if (
        state.data.filter(
          (chat) => parseInt(chat.id) === parseInt(payload.ch_id)
        ).length > 0
      ) {
        let arr = [];
        let bool = payload.bool;
        let active = state.activeChat;
        state.data.map((chat) => {
          if (parseInt(chat.id) === parseInt(payload.ch_id)) {
            if (
              state.activeChat?.id &&
              parseInt(state.activeChat.id) === parseInt(payload.ch_id)
            ) {
              active = bool
                ? {
                    ...state.activeChat,
                    messages: active.messages.map((msg) => {
                      if (parseInt(msg.id) !== parseInt(payload.msg_id)) {
                        return msg;
                      } else {
                        return {
                          ...msg,
                          auth_message_status: {
                            ...(msg?.auth_message_status || {}),
                            is_deleted: 1,
                          },
                        };
                      }
                    }),
                  }
                : {
                    ...state.activeChat,
                    messages: active.messages.filter(
                      (msg) => parseInt(msg.id) !== parseInt(payload.msg_id)
                    ),
                  };
            }
            arr.push({
              ...chat,
              messages: chat.messages.map((msg) => {
                if (parseInt(msg.id) !== parseInt(payload.msg_id)) {
                  return msg;
                } else {
                  return {
                    ...msg,
                    auth_message_status: {
                      ...(msg?.auth_message_status || {}),
                      is_deleted: 1,
                    },
                  };
                }
              }),
            });
          } else {
            arr.push(chat);
          }
        });
        return {
          ...state,
          data: arr,
          activeChat: active,
        };
      }
    }
    case "DELETE_CALL": {
      return {
        ...state,
        calls: state.calls.filter(
          (call) => parseInt(call.id) !== parseInt(payload)
        ),
      };
    }
    case "REPLY-MESSAGE": {
      return {
        ...state,
        replyMessage: payload,
      };
    }
    default:
      return state;
  }
};

const initialState = {
  orderLoading: false,
  cart: [],
  addressLists: [],
  center: null,
