    location: { latitude: null, longitude: null },
    Country: { name: "Turkey", code: "TR" },

    address_detail: "",
    address: "",
    contact_info: {
      contact_person_name: "",
      phone: "",
      alternative_phone: "",
    },
    region: "",
    region_details: {
      city: "",
      province: "",
      town: "",
      street: "",
      building: "",
    },
  },
  orderData: {
    payment: [],
    coupon: false,
    agree: false,
    coupon_number: "",
    loading: false,
    success: false,
  },
  enable: false,
  AddToCartOption: {
    enable: false,
    selectedSize: null,
    selectedColor: {},
    quantity: 0,
    price: null,
    UID: "",
    selectedOptions: [],
  },
  SelectedProduct: null,
