    prices: {
      min: 0,
      max: 500,
      pricesWord: null,
    },
    pricesSelected: [],
    brands: [],
    offers: [],
    sizes: [],
    searchText: "",
    colors: [],
  },
  filterLoading: false,
  activeFilters: {
