export const getMessageTime = (lastMessage) => {
  if (lastMessage.created_at) {
    let d = new Date(lastMessage.created_at);
    return `${d.getHours() > 9 ? d.getHours() : "0" + d.getHours()}:${
      d.getMinutes() > 9 ? d.getMinutes() : "0" + d.getMinutes()
    }`;
  }
};
export const isNew = (ch) => {
  let a = ch?.filter(
    (mes) =>
      !mes.message_type.name.includes("Call") &&
      mes.sender_user_id !== getUserChat()?.id &&
      mes.message_status.filter((st) => st.user_id === getUserChat()?.id)[0]
        ?.is_watched === false
  ).length;
