const uploadFile = async (file_name, file, onUploadProgress) => {
  let formData = new FormData();
  formData.append("file", file);
  formData.append("file_name", file_name);
  let axios = (await import("axios")).default;
  return axios.post(
    process.env.NEXT_PUBLIC_CHAT_BACKEND_URL + "/api/v1/upload_file",
    formData
  );
};

export const upload = async (file) => {
  let currentFile = file;
  let a = "",
    b = "";
  await uploadFile(currentFile.name?.split(".")[0] || "image", file)
    .then((response) => {
      a = response.data.data.file_path;
      b = currentFile.name;
      return { path: response.data.data.file_path, name: currentFile.name };
    })
    .catch((e) => {
      console.error(e);
    });
  return { path: a, name: b };
};
export function dataURLtoFile(dataurl, filename) {
  var arr = dataurl.split(","),
    mime = arr[0]?.match(/:(.*?);/)[1],
    bstr = atob(arr[arr.length - 1]),
    n = bstr.length,
    u8arr = new Uint8Array(n);
  while (n--) {
    u8arr[n] = bstr.charCodeAt(n);
  }
  return new File([u8arr], filename, { type: mime });
}
export function blobToDataURL(blob, callback) {
  var a = new FileReader();
  a.onload = function (e) {
    callback(e.target.result);
  };
  a.readAsDataURL(blob);
}
export const showDate = (d) => {
  const language = store.getState().homepage.language;
  var days = [
    translateFunction("Sunday", language),
    translateFunction("Monday", language),
    translateFunction("Tuesday", language),
    translateFunction("Wednesday", language),
    translateFunction("Thursday", language),
    translateFunction("Friday", language),
    translateFunction("Saturday", language),
  ];
  let now = new Date();
  let nowString = `${now.getFullYear()}-${
    now.getMonth() + 1 > 9
      ? (now.getMonth() + 1).toString()
      : "0" + (now.getMonth() + 1).toString()
  }-${
    now.getDate() > 9 ? now.getDate() : "0" + parseInt(now.getDate()).toString()
  }`;
  d = new Date(d);
  let date_mes = new Date(d);
  d = `${d.getFullYear()}-${
    d.getMonth() + 1 > 9
      ? (d.getMonth() + 1).toString()
      : "0" + (d.getMonth() + 1).toString()
  }-${d.getDate() > 9 ? d.getDate() : "0" + parseInt(d.getDate()).toString()}`;

  let day = new Date(d);
  day = days[day.getDay()];
  if (d === nowString)
    return `${
      date_mes.getHours() > 9 ? date_mes.getHours() : "0" + date_mes.getHours()
    }:${
      date_mes.getMinutes() > 9
        ? date_mes.getMinutes()
        : "0" + date_mes.getMinutes()
    }`;
  else if (new Date(nowString) - new Date(d) === 86400000) {
    return translate("Yesterday", language);
  } else if (new Date(nowString) - new Date(d) < 86400000 * 6) return day;
  else return language === "ar" ? d.toLocaleString("ar-EG") : d;
};

import { useDispatch, useSelector } from "react-redux";
import ChatIcon from "public/svg/ChatIcon.svg";
import { Sendevent, translateFunction } from "utils/functions";
import UserAvatar from "./UserAvatar";
import { ChatConroller } from "store/chat/actions";
import { getNew } from "components/Chat/chatsFunctions";
import ChatNotification from "./ChatNotification";
import { useParams } from "next/navigation";

function AuthNavSection() {
  let { lang } = useParams();
  // @ts-ignore
  let languageVariable = lang.split("-")[1];
  const translate = (key, lang) => {
    return translateFunction(key, languageVariable);
  };
  const language = useSelector(
    (state: StateInterface) => state.homepage.language
  );
  const chatVar = useSelector((state: StateInterface) => state.chat.chatVar);
  const user = useSelector((state: StateInterface) => state.auth.user);

  const chats = useSelector((state: StateInterface) => state.chat.data);
  const dispatch = useDispatch();

  return (
    <>
      {
        <div
          className={`${chatVar && "active-nav-item"} nav-question-item`}
          style={{
            marginRight:
              (!chatVar && getNew(chats).length === 0) || chatVar
                ? "30px"
                : "20px",
            marginLeft: "30px",
            transform:
              !chatVar && getNew(chats).length > 0 && "translateY(-1px)",
          }}
          onClick={() => {
            Sendevent({
              event: "button_clicked",
              value: "chat_nav_bar_button",
            });
            dispatch(ChatConroller(true));
          }}
        >
          {!chatVar && getNew(chats).length === 0 ? (
            <ChatIcon />
          ) : (
            !chatVar && <ChatNotification num={getNew(chats).length} />
          )}
          {chatVar && <ChatIcon />}
        </div>
      }

      <div
        className={`welcome-user ${language + "-medium"}`}
        style={{ marginRight: "12px", marginLeft: "0px" }}
      >
        {translate("Hello", language)} {user?.name && <span>,</span>}{" "}
        <span className={`${language + "-light"}`}>{user?.name}</span>
      </div>
      <UserAvatar
        avatar={user?.avatar?.src ?? user.avatar}
      />
    </>
  );
}

