interface TimerProps {
  onFinish: Function;
  onResume: Function;
}
function Timer({ onFinish }: TimerProps) {
  const timer = useTimer({
    create: {
      timerWithDuration: {
        time: {
          // Set a duration of 1 minute and 30 seconds
          minutes: 1,
          seconds: 59,
        },
      },
    },
