          // @ts-ignore
          value={parseInt(inputValue)}
          data-cy="QuantityInCart"
          max={max}
          disabled
          onChange={(e) => {}}
          className="outline-none hide-btn text-[14px] medium text-[#1D1D1D] text-center max-w-[72px] border-none py-1  w-[72px] h-[24px]"
        />
