import React, { useState } from "react";
import ActiveCategoryIcon from "public/svg/listing/ActiveCategoryIcon.svg";
import SubCategoryCircle from "./SubCategoryCircle";
import { useDispatch, useSelector } from "react-redux";
import { filterProducts, Sendevent, UpdateFilter } from "utils/functions";
import { useParams, useSearchParams } from "next/navigation";

function CategoryCircle({ category }) {
  const selectedFilter = useSelector(
    (state: StateInterface) => state.details.selectedFilter
  );
  const filterEnabled = useSelector(
    (state: StateInterface) => state.listing.filterEnabled
  );
  const filters = useSelector((state: StateInterface) => state.details.filters);
  const dispatch = useDispatch();
  const pathName = useParams();
  const params = useSearchParams();
  const selectCategory = (e) => {
    Sendevent({
      event: "button_clicked",
      value: "add_filter_button",
      extra: {
        type: "category",
        name: e.name,
      },
    });
    if (
      selectedFilter.categories.filter((s) =>
        category.childes.map((sub) => sub.slug).includes(s.slug)
      ) &&
      selectedFilter.categories.filter((s) => s.slug === category.slug).length >
        0
    ) {
      let arr = selectedFilter.categories.filter((s) =>
        category.childes.map((sub) => sub.slug).includes(s.slug)
      );
      arr.map((s) => {
        dispatch({ type: "FILTER-CATEGORY", payload: s });
      });
    }
    dispatch({ type: "FILTER-CATEGORY", payload: e });
    dispatch({ type: "FILTER-LOADING", payload: true });
    UpdateFilter({
      boutiqueId: pathName.productCategory,
      lang: pathName.lang,
      sizesAttr: filters.sizesAttr,
      newFiltersCallback: ({ filtersVar }) => {
        dispatch({ type: "EDIT-FILTER", payload: filtersVar });
      },
      searchText: "",
      done: () => {
        dispatch({ type: "FILTER-LOADING", payload: false });
      },
    });
    if (!filterEnabled) {
      filter();
    } else {
    }
  };
  const filter = () => {
    dispatch({ type: "FILTER-START" });
    dispatch({ type: "Skeleton-Listing" });
    filterProducts({
      boutiqueId:
        (params.get("boutique_slugs") && params.get("boutique_slugs")) ||
        pathName.productCategory,
      lang: pathName.lang,
      sizesAttr: filters.sizesAttr,
      callback: (products) => {
        dispatch({ type: "GET_PRODUCT", payload: { products } });
      },
      offset: 1,
      storeCallback: (e) => {
        dispatch({
          type: "ACTIVE-FILTER",
          payload: e,
        });
      },
      newFiltersCallback: ({ filtersVar }) => {
        dispatch({ type: "EDIT-FILTER", payload: filtersVar });
      },
    });
  };
  const isSelected = () => {
    return (
      selectedFilter.categories.filter((s) => s.slug === category.slug).length >
      0
    );
  };
  const isSelectedChild = () => {
    if (
      selectedFilter.categories.filter(
        (s) => category.childes.filter((sub) => sub.slug === s.slug).length > 0
      ).length > 0
    )
      return true;
    else return false;
  };
  const [expanded, setExpanded] = useState(isSelected() || isSelectedChild());

  return (
    <>
      <div
        onClick={() => {
          if (expanded && !isSelected()) {
            selectCategory({ ...category });
          } else if (expanded || isSelected()) {
            selectCategory({ ...category });
            if (!isSelectedChild()) {
              setExpanded(false);
            }
          } else {
            selectCategory({ ...category });
            setExpanded(!expanded);
          }
        }}
        className={`category-circle flex-col align-center ${
          category?.categories_sub?.length > 0 && "extended-circle"
        }`}
        data-cy="category_botiquePage"
      >
