"use client";
import React, { useEffect, useState } from "react";
import "styles/listing-components.css";
import SearchIcon from "public/svg/listing/searchIcon.svg";
import SortIcon from "public/svg/listing/sortIcon.svg";
import FilterIcon from "public/svg/listing/filterIcon.svg";
import ShareIcon from "public/svg/listing/shareIcon.svg";
import BackIcon from "public/svg/listing/backIcon.svg";
import BoutiqueHeader from "./BoutiqueHeader";
import FilterInfoBar from "./FilterInfoBar";
import { useDispatch, useSelector } from "react-redux";
import {
  expandView,
  filterProducts,
  normalizeView,
  Sendevent,
  UpdateFilter,
} from "utils/functions";
import FloatingInfoBar from "./filterComponents/FloatingInfoBar";
import { dispatchRouteChangeEvent } from "utils/events";
import {
  useParams,
  usePathname,
  useRouter,
  useSearchParams,
} from "next/navigation";
import NextLink from "components/global/NextLink";
import { DebounceInput } from "node_modules/react-debounce-input/src";

function FilterBar({ boutique, filters, productsServer }) {
  const selectedFilter = useSelector(
    (state: StateInterface) => state.details.selectedFilter
  );

  const pathName = useParams();
  const dispatch = useDispatch();
  const setEnableFilter = (e) => {
    dispatch({ type: "filterEnabled", payload: e });
  };
  const filterEnabled = useSelector(
    (state: StateInterface) => state.listing.filterEnabled
  );
  const activeFilters = useSelector(
    (state: StateInterface) => state.details.activeFilters
  );
  const selectedFilters = useSelector(
    (state: StateInterface) => state.details.selectedFilter
  );
  const products = useSelector(
    (state: StateInterface) => state.listing.products
  );
  const ActiveSearch = useSelector(
    (state: StateInterface) => state.details.search
  );
  const sizesAttr = useSelector(
    (state: StateInterface) => state.details.filters.sizesAttr
  );
  const showFilterInfoBar = () => {
    if (
      selectedFilter.categories.length > 0 ||
      selectedFilter.brands.length > 0 ||
      selectedFilter.sizes.length > 0 ||
      selectedFilter.colors.length > 0 ||
      selectedFilter.offers.length > 0 ||
      activeFilters.prices?.pricesWord ||
      selectedFilter.searchText?.length > 0
    ) {
      return true;
    } else {
      return false;
    }
  };
  const searchParams = useSearchParams();
  const pathname = usePathname();
  const paramsVar = useParams();
  const router = useRouter();
  const onChange = (e) => {
    dispatch({ type: "FILTER-LOADING", payload: true });
    dispatch({ type: "SEARCH-FILTER", payload: e.target.value });
    UpdateFilter({
      sizesAttr: sizesAttr,
      boutiqueId: pathName.productCategory,
      lang: pathName.lang,
      done: () => {
        dispatch({ type: "FILTER-LOADING", payload: false });
      },
      newFiltersCallback: ({ filtersVar }) => {
        dispatch({
          type: "EDIT-FILTER",
          payload: { ...filtersVar },
        });
      },
      searchText: e.target.value,
    });
    if (filterEnabled) {
    } else {
      const params = new URLSearchParams(searchParams);
      dispatch({ type: "Skeleton-Listing" });
      filterProducts({
        serachTrigger: true,
        boutiqueId:
          (params.get("boutique_slugs") && params.get("boutique_slugs")) ||
          pathName.productCategory,
        lang: paramsVar.lang,
        sizesAttr: sizesAttr,
        callback: (products) => {
          dispatch({ type: "GET_PRODUCT", payload: { products } });
        },
        offset: 1,
        storeCallback: (e) => {
          dispatch({
            type: "ACTIVE-FILTER",
            payload: e,
          });
        },
        newFiltersCallback: ({ filtersVar }) => {
          dispatch({ type: "EDIT-FILTER", payload: filtersVar });
        },
        searchText: e.target.value,
      });
      setEnableFilter(false);
      if (e.target.value > 0) {
        params.set("searchText", e.target.value);
      } else {
        params.delete("searchText");
      }
      // @ts-expect-error 'shallow' does not exist in type 'NavigateOptions'
      router.replace(`${pathname}?${params.toString()}`, { shallow: true });
    }
  };

  useEffect(() => {
    let filtersVar = {
      categories: filters?.categories || [],
      brands: filters?.brands || [],
      attributes: filters?.attributes || [],
      offers: filters?.offers || [],
      prices: filters?.prices || null,
      search_text: filters?.result_for || "",
      colors: filters?.colors || [],
    };

    dispatch({ type: "FILTER-INIT", payload: filtersVar });
  }, []);
  return (
    <>
      <div className="filter-listing-bar relative flex-row align-center">
        <NextLink
          href={filterEnabled ? "#" : "/"}
          className="back-icon"
          data-cy="backIcon_pageAfterClickSearchTotal"
          onClick={() => {
            if (!filterEnabled) {
              // router.push(`/`);
              Sendevent({
                event: "button_clicked",
                value: "back_app_button",
              });
              dispatch({ type: "RESET-FILTERS" });

              // dispatchRouteChangeEvent("start", {
              //   to: "HomePage",
              //   from: "details",
              // });

              // document.documentElement.style.overflow = "hidden";
              // document.documentElement.scrollTop = 0;
            } else {
              dispatch({ type: "RESET-SELECTED-Back" });

              UpdateFilter({
                filtersVar: {
                  categories: activeFilters.categories,
                  brands: activeFilters.brands,
                  colors: activeFilters.colors,
                  sizes: activeFilters.sizes,
                },
                sizesAttr: sizesAttr,
                boutiqueId: pathName.productCategory,
                lang: pathName.lang,
                done: () => {
                  dispatch({ type: "FILTER-LOADING", payload: false });
                },
                newFiltersCallback: ({ filtersVar }) => {
                  dispatch({
                    type: "EDIT-FILTER",
                    payload: { ...filtersVar, reset: false },
                  });
                },
                searchText: selectedFilter?.searchText,
              });
              setEnableFilter(false);
              normalizeView();
            }
          }}
        >
          <BackIcon data-cy="back_icon_boutique_page" />
        </NextLink>
        <div
          className={`filter-bar-options flex-row align-center ${
            ActiveSearch && "w-full"
          }`}
        >
          <div
            className={`filter-option transition-all filter-search-option relative ${
              ActiveSearch &&
              "w-[75%] [&>input]:w-full [&>input]:bg-[#f8f8f8] [&>input]:h-[40px]"
            }`}
            data-cy="searchIcon_boutiquePage"
            onClick={() => {
              Sendevent({
                event: "button_clicked",
                value: "open_search_field_button",
              });
              document
                .querySelector<HTMLInputElement>("#filter-search")
                ?.focus();
              if (
                document.querySelector<HTMLInputElement>(
                  ".boutique-logo-container"
                )
              )
                document.querySelector<HTMLInputElement>(
                  ".boutique-logo-container"
                ).style.display = "none";
              dispatch({ type: "FILTER-SEARCH-ENABLE", payload: true });
            }}
          >
            <DebounceInput
              data-cy="inputFiled"
              id="filter-search"
              debounceTimeout={400}
              value={selectedFilters.searchText}
              onBlur={() => {
                if (selectedFilters?.searchText.length === 0) {
                  if (
                    document.querySelector<HTMLInputElement>(
                      ".boutique-logo-container"
                    )
                  )
                    document.querySelector<HTMLInputElement>(
                      ".boutique-logo-container"
                    ).style.display = "flex";
                  dispatch({ type: "FILTER-SEARCH-ENABLE", payload: false });
                }
              }}
              onChange={(e) => {
                onChange(e);
              }}
              onKeyDown={(e) => {
                //@ts-ignore
                if (e.keyCode == 13) {
                  const params = new URLSearchParams(searchParams);
                  dispatch({ type: "Skeleton-Listing" });
                  filterProducts({
                    serachTrigger: true,
                    boutiqueId:
                      (params.get("boutique_slugs") &&
                        params.get("boutique_slugs")) ||
                      pathName.productCategory,
                    lang: paramsVar.lang,
                    sizesAttr: sizesAttr,
                    callback: (products) => {
                      dispatch({ type: "GET_PRODUCT", payload: { products } });
                    },
                    offset: 1,
                    storeCallback: (e) => {
                      dispatch({
                        type: "ACTIVE-FILTER",
                        payload: e,
                      });
                    },
                    newFiltersCallback: ({ filtersVar }) => {
                      dispatch({ type: "EDIT-FILTER", payload: filtersVar });
                    },
                    searchText: selectedFilters.searchText,
                  });
                  setEnableFilter(false);
                  if (selectedFilters.searchText.length > 0) {
                    params.set("searchText", selectedFilters.searchText);
                  } else {
                    params.delete("searchText");
                  }
                  router.replace(`${pathname}?${params.toString()}`, {
                    // @ts-expect-error 'shallow' does not exist in type 'NavigateOptions'

                    shallow: true,
                  });
                  // @ts-ignore
                  e.target.blur();
                }
              }}
              className={`${
                ActiveSearch && "pl-[40px]"
              } rounded-[15px]  w-0 h-full border-0 outline-none text-[#5d5d5d]`}
            />
            <SearchIcon
              className={`absolute z-10 ${
                ActiveSearch ? "top-[9px] left-[14px]" : "top-0 left-0"
              }`}
            />
          </div>
          <div className="filter-option">
            <SortIcon data-cy="closeSearchInput" />
          </div>
          <div
            className="filter-option"
            data-cy="settingsIcon"
            onClick={() => {
              setEnableFilter(!filterEnabled);

              if (filterEnabled) {
                Sendevent({
                  event: "button_clicked",
                  value: "filter_close_icon_button",
                });
                normalizeView();
              } else {
                Sendevent({
                  event: "button_clicked",
                  value: "product_listing_filter_icon_button",
                });
                expandView({ filter: true });
                window.scrollTo({ top: 0 });
              }
            }}
          >
            {(products.length > 1 || productsServer?.length > 1) && (
              <FilterIcon
                className={`${filterEnabled && "filter-icon-enabled"}`}
              />
            )}
          </div>
          <div
            className="filter-option"
            onClick={() => {
              let url = document.location.href;

              navigator.clipboard.writeText(url).then(
                function () {},
                function () {}
              );
            }}
          >
            <ShareIcon />
          </div>
        </div>
      </div>
      <BoutiqueHeader
        boutique={boutique}
        showFilters={products?.length > 1 || productsServer?.length > 1}
      />
      {!filterEnabled && showFilterInfoBar() && (
        <FilterInfoBar filtersVariable={activeFilters} />
      )}
      {filterEnabled && showFilterInfoBar() && <FloatingInfoBar />}
    </>
  );
}

export default FilterBar;

function PointsSlider({
  isActiveTopSlide,
  setActiveTopSlide,
  activeIndex,
  colors,
}: {
  isActiveTopSlide: boolean;
  setActiveTopSlide: Function;
  activeIndex: number;
  colors: any[];
}) {
  const getSize = (i) => {
    if (i === activeIndex || (i === activeIndex && i === 0)) return 6;
    else if (i === activeIndex - 1 || i === activeIndex + 1) return 4;
    else return 2;
  };

  return (
    <>
      {!isActiveTopSlide && (
        <div
          className="top-slider-enable align-center flex absolute justify-center cursor-pointer"
          onClick={() => {
            setActiveTopSlide();
          }}
        >
          {colors.map((img, i) => (
            <div
              key={i}
              className={`slider-point-item rounded-50 relative wid-${getSize(
                i
              )} ${activeIndex === i && "active-point-item"}`}
            >
              {getSize(i) === 2 ? (
                <svg
                  className="absolute"
                  xmlns="http://www.w3.org/2000/svg"
                  xmlnsXlink="http://www.w3.org/1999/xlink"
                  width="2"
                  height="2"
                >
                  <g>
                    <g stroke="#3c3c3c" strokeWidth="0.3">
                      <circle cx="1" cy="1" r="0.85" fill="none" />
                    </g>
                  </g>
                </svg>
              ) : getSize(i) === 4 ? (
                <svg
                  className="absolute"
                  xmlns="http://www.w3.org/2000/svg"
                  xmlnsXlink="http://www.w3.org/1999/xlink"
                  width="4"
                  height="4"
                >
                  <g>
                    <g stroke="#3c3c3c" strokeWidth="0.3">
                      <circle cx="2" cy="2" r="1.85" fill="none" />
                    </g>
                  </g>
                </svg>
              ) : (
                getSize(i) === 6 && (
                  <svg
                    className="absolute"
                    xmlns="http://www.w3.org/2000/svg"
                    xmlnsXlink="http://www.w3.org/1999/xlink"
                    width="6"
                    height="6"
                  >
                    <g>
                      <g
                        id="Ellipse_4-2"
                        data-name="Ellipse 4"
                        fill="none"
                        stroke="#3c3c3c"
                        strokeWidth="0.3"
                      >
                        <circle cx="3" cy="3" r="2.85" fill="none" />
                      </g>
                    </g>
                  </svg>
                )
              )}
            </div>
          ))}
        </div>
      )}
    </>
  );
}

export default PointsSlider;

"use client";
import { useEffect } from "react";
import { Swiper, SwiperSlide } from "swiper/react";

import { useRef } from "react";
import PointsSlider from "./PointsSlider";
import { getConfiguredImage } from "utils/functions";
function ImageSlider({
  renderVar,
  product_name,
  active,
  isColorSelected,
  setActiveImage,
  activeColor,
  isActiveTopSlide,
  setActiveTopSlide,
  setColor,
  priority,
}: {
  renderVar: boolean;
  product_name: string;
  active: boolean;
  isColorSelected: boolean;
  setActiveImage: Function;
  activeColor: any;
  isActiveTopSlide: boolean;
  setActiveTopSlide: Function;
  setColor: Function;
  priority: boolean;
}) {
  var ColorRef = useRef<any>();
  useEffect(() => {
    if (activeColor.index >= 0) {
      ColorRef.current.slideTo(activeColor.index, 300, false);
    }
  }, [activeColor]);
  return (
    <>
      <div
        className={"active-slider " + (active ? "sl-active" : "sl-deactive")}
      >
        {!isColorSelected && (
          <PointsSlider
            key={product_name}
            colors={activeColor.images}
            activeIndex={ColorRef.current?.activeIndex || 0}
            isActiveTopSlide={isActiveTopSlide}
            setActiveTopSlide={() => {
              setActiveTopSlide(!isActiveTopSlide);
              setColor(true);
            }}
          />
        )}

        <Swiper
          effect="coverflow"
          id={product_name}
          coverflowEffect={{
            depth: 100,
            modifier: 1,
            scale: 0.78,
            stretch: 135,
            slideShadows: false,
          }}
          ref={ColorRef}
          threshold={1}
          onInit={(swiper) => {
            ColorRef.current = swiper;
          }}
          speed={100}
          slidesPerView={1}
          centeredSlides={true}
          onSlideChange={(swiper) => {
            setActiveImage({ ...activeColor, index: swiper.activeIndex });
          }}
          initialSlide={activeColor.index}
          loop={false}
        >
          {activeColor?.images?.map((img, i) => (
            <SwiperSlide
              key={i}
              style={{
                overflow: "visible",
                position: "relative",
              }}
            >
              {({ isActive }) => (
                <>
                  {/* <BorderImage isBig={true} /> */}
                  <div className="inset-shadow-img w-100 h-100 rounded-15 absolute" />
                  {(isActive || i === 0) && (
                    <img
                      loading={priority && i === 0 ? "eager" : "lazy"}
                      fetchPriority={priority && i === 0 ? "high" : "low"}
                      style={{ borderRadius: "15px", zIndex: "3" }}
                      src={getConfiguredImage({
                        src: img.file_path,
                        width: 400,
                        height: 400,
                      })}
                      key={`${product_name}-${i}`}
                      alt={product_name || "alt"}
                    />
                  )}
                </>
              )}
            </SwiperSlide>
          ))}
        </Swiper>
      </div>
    </>
  );
}

export default ImageSlider;

"use client";

import { useParams } from "next/navigation";
import { dispatchRouteChangeEvent } from "utils/events";
import { GetAppLanguage, translateFunction } from "utils/functions";

function BuyButton({ buy }) {
  let { lang } = useParams();
  // @ts-ignore
  let languageVariable = lang.split("-")[1];
  const translate = (key, lang) => {
    return translateFunction(key, languageVariable);
  };
