  };
  const searchParams = useSearchParams();
  useEffect(() => {
    if (searchParams.get("color")) {
      let color = colors.filter(
        (s) => s.color_name === searchParams.get("color")
      )[0];
      if (color) dispatch({ type: "AddToCartColor", payload: color });
    }
  }, []);
  const getInitial = () => {
    if (searchParams.get("color")) {
      let index = 0;
      colors.map((s, i) => {
        if (s.color_name === searchParams.get("color")) index = i;
      });
      return index;
    }

    return 0;
  };
  const ref = useRef<SwiperRef>();
  return (
    <Swiper
      modules={[EffectCoverflow]}
      speed={100}
      style={{
        width: "100%",
        margin: "0",
      }}
      effect="coverflow"
      className="mt-[10px] "
      coverflowEffect={{
        rotate: 0,
        depth: 120,
        modifier: 1,
        scale: 1,
        stretch: 20,
        slideShadows: false,
      }}
      onSlideChange={(e) => {
        setActive(colors[e.activeIndex]);
      }}
      slidesPerView={7}
      initialSlide={getInitial()}
      threshold={1}
      centeredSlides={true}
      loop={false}
      ref={ref}
    >
      {colors?.map((color, i) => (
        <SwiperSlide
          onClick={() => {
            ref.current.swiper.slideTo(i, 400, false);
            setActive(color);
          }}
          key={i}
          style={{
            overflow: "visible",
            minWidth: "70px",
            height: "70px",
          }}
          className="w-[70px] h-[70px] color-swipe-slide relative rounded-full"
        >
          {({ isActive }) => (
            <>
              <img
                className="w-[70px] h-[70px] rounded-full"
                src={getConfiguredImage({
                  src:
                    (typeof color.images[0] === "string" && color.images[0]) ||
                    color.images[0].file_path,
                  width: 400,
                  height: 400,
                })}
              />
              {isActive && (
                <span className="regular text-[#3C3C3C] text-[14px] absolute bottom-[-20px] w-full flex justify-center items-center">
                  {color.color_name}
                </span>
              )}
            </>
          )}
        </SwiperSlide>
      ))}
    </Swiper>
  );
};

