function Comments({
  comments,
  Render,
  resendComment,
  productId,
  ErrorAccure,
  CommentsData,
  setComments,
  increase_comments,
  setRender,
  verifyCommentAction,
}) {
  const user = useSelector((state: StateInterface) => state.auth.user);
  useEffect(() => {}, [Render, comments]);
  const resendCommentApi = async (mid, s) => {
    try {
      let req: AddComment = await AxiosPost({
        url: process.env.NEXT_PUBLIC_BACKEND_URL + "/customer/product_comment",
        title: "resend add Comment For Product",
        body: {
          customer_id: user?.id,
          product_id: productId,
          comment: s,
        },
      });
      if (req?.comment) {
        let s = CommentsData.filter((m) => m.mid === mid)[0];
        verifyCommentAction(mid);
        increase_comments();
        setRender(!Render);
      } else {
        ErrorAccure(mid);
      }
    } catch (e) {
      ErrorAccure(mid);
    }
  };
  return (
    <div className="content-extended comments-extended">
      {/* <CommentItem
        date="18 feb"
        name="Yxxx Oxxx"
        text="Amazing Product I Buy It And I Saw It Is Good Quality Regarding Price"
        photo="https://res.cloudinary.com/dtcmozf4d/image/upload/h_100/f_avif/q_100/v1/product/thumbnail/2024-05-12-663fce81803c3.png"
      /> */}
      {CommentsData !== null ? (
        CommentsData.map((s, i) => (
          <CommentItem
            isPending={s.is_verfied}
            resendComment={() => {
              resendComment(s.mid);
              resendCommentApi(s.mid, s.comment);
            }}
            isError={s.isError}
            key={i}
            date={showDate(s.created_at)}
            name={s?.customer?.name}
            text={s?.comment}
            photo="https://res.cloudinary.com/dtcmozf4d/image/upload/h_100/f_avif/q_100/v1/product/thumbnail/2024-05-12-663fce81803c3.png"
          />
        ))
      ) : (
        <>
          <Skeleton
            width={"100%"}
            height={"100px"}
            borderRadius={20}
            className="comment-item"
          ></Skeleton>
          <Skeleton
            width={"100%"}
            height={"100px"}
            borderRadius={20}
            className="comment-item"
          ></Skeleton>
        </>
      )}
    </div>
  );
}

