import React, { useRef, useState } from "react";
import { Swiper, SwiperSlide } from "swiper/react";
import { getConfiguredImage } from "utils/functions";
import "styles/listing.css";
function GalleryItemSlider({ images }) {
  const SliderRef = useRef<any>();
  const [active, setActive] = useState(0);
  return (
    <div className="relative flex-col ">
      {images.length > 0 && (
        <PointsSlider images={images} activeIndex={active} />
      )}
      <Swiper
        effect="coverflow"
        onSlideChange={(e) => {
          setActive(e.activeIndex);
        }}
        coverflowEffect={{
          depth: 100,
          modifier: 1,
          scale: 0.78,
          stretch: 135,
          slideShadows: false,
        }}
        ref={SliderRef}
        threshold={1}
        onInit={(swiper) => {
          SliderRef.current = swiper;
        }}
        speed={100}
        slidesPerView={1}
        centeredSlides={true}
        initialSlide={0}
        loop={false}
      >
        {images.map((img, i) => (
          <SwiperSlide
            key={i}
            style={{
              overflow: "visible",
              position: "relative",
            }}
          >
            {({ isActive }) => (
              <>
                <svg
                  className="absolute top-0 left-0 z-50"
                  xmlns="http://www.w3.org/2000/svg"
                  width="calc(100% - 1px)"
                  height="calc(100%)"
                >
                  <g
                    id="Rectangle_5686"
                    data-name="Rectangle 5686"
                    fill="none"
                    stroke="#fff"
                    strokeWidth="0.5"
                  >
                    <rect width="100%" height="100%" rx="30" stroke="none" />
                    <rect
                      x="0.25"
                      y="0.25"
                      width="calc(100% - 1px)"
                      height="calc(100%)"
                      rx="29.75"
                      fill="none"
                    />
                  </g>
                </svg>

                <div className="inset-shadow-img w-100 h-100 rounded-[30px] absolute z-40" />
                <img
                  className="w-full max-h-[595px] rounded-[30px]"
                  src={getConfiguredImage({
                    src: img,
                    width: 400,
                    height: 400,
                  })}
                />
              </>
            )}
          </SwiperSlide>
        ))}
      </Swiper>
    </div>
  );
}
function PointsSlider({
  activeIndex,
  images,
}: {
  activeIndex: number;
  images: any[];
}) {
  const getSize = (i) => {
    if (i === activeIndex || (i === activeIndex && i === 0)) return 6;
    else if (i === activeIndex - 1 || i === activeIndex + 1) return 4;
    else return 2;
  };

  return (
    <>
      <div className="top-slider-enable align-center flex absolute justify-center cursor-pointer">
        {images.map((img, i) => (
          <div
            key={i}
            className={`slider-point-item rounded-50 relative wid-${getSize(
              i
            )} ${activeIndex === i && "active-point-item"}`}
          >
            {getSize(i) === 2 ? (
              <svg
                className="absolute"
                xmlns="http://www.w3.org/2000/svg"
                xmlnsXlink="http://www.w3.org/1999/xlink"
                width="2"
                height="2"
              >
                <g>
                  <g stroke="#3c3c3c" strokeWidth="0.3">
                    <circle cx="1" cy="1" r="0.85" fill="none" />
                  </g>
                </g>
              </svg>
            ) : getSize(i) === 4 ? (
              <svg
                className="absolute"
                xmlns="http://www.w3.org/2000/svg"
                xmlnsXlink="http://www.w3.org/1999/xlink"
                width="4"
                height="4"
              >
                <g>
                  <g stroke="#3c3c3c" strokeWidth="0.3">
                    <circle cx="2" cy="2" r="1.85" fill="none" />
                  </g>
                </g>
              </svg>
            ) : (
              getSize(i) === 6 && (
                <svg
                  className="absolute"
                  xmlns="http://www.w3.org/2000/svg"
                  xmlnsXlink="http://www.w3.org/1999/xlink"
                  width="6"
                  height="6"
                >
                  <g>
                    <g
                      id="Ellipse_4-2"
                      data-name="Ellipse 4"
                      fill="none"
                      stroke="#3c3c3c"
                      strokeWidth="0.3"
                    >
                      <circle cx="3" cy="3" r="2.85" fill="none" />
                    </g>
                  </g>
                </svg>
              )
            )}
          </div>
        ))}
      </div>
    </>
  );
}
export default GalleryItemSlider;

"use client";

import React, { useEffect, useState } from "react";
import "styles/cameraShot.css";
import CameraShotIcon from "public/svg/product/CameraShotIcon.svg";
import ColorsInfo from "public/svg/product/colorsInfo.svg";
import { useDispatch, useSelector } from "react-redux";
import { useSwipeable } from "react-swipeable";
import GalleryItem from "./GalleryItem";
import { translateFunction } from "utils/functions";
import { useParams } from "next/navigation";
function CameraShotGallery({ images, close }) {
  let { lang } = useParams();
  // @ts-ignore
  let languageVariable = lang.split("-")[1];
  const translate = (key, lang?) => {
    return translateFunction(key, languageVariable);
  };
  const [extended, setExtended] = useState(false);
  const activeCameraGallery = useSelector(
    (state: StateInterface) => state.details.activeCameraGallery
  );
  const dispatch = useDispatch();
  var dir = 0;
  const swipeToClose = (e) => {
    let container = document.querySelector(".container-gallery");

    if (container.scrollTop === 0 && Math.abs(e.deltaY) > 50) {
      if (activeCameraGallery) {
        close();
      }
    }
  };
  const scrollToClose = (e) => {
    let container = document.querySelector(".container-gallery");

    if (
      container &&
      container.scrollTop === 0 &&
      e.deltaY < 0 &&
      Math.abs(e.deltaY) > 50
    ) {
      close();
    }
  };
  const handlers = useSwipeable({
    onSwipedDown: (e) => {
      swipeToClose(e);
    },

    delta: 10,
    trackMouse: true,
    trackTouch: true,

    touchEventOptions: {
      passive: false,
    },
  });
  useEffect(() => {
    window.addEventListener("wheel", function (e) {
      scrollToClose(e);
    });
  }, []);
  return (
    <>
      <div
        className={`bg-[#1D1D1D] fixed transition-all ${
          activeCameraGallery ? "top-0" : "top-[110vh]"
        } left-0 h-[100vh] min-w-[100vw] z-[9999999999]`}
        onClick={() => {
          close();
        }}
      />
      <div
        {...handlers}
        className={`flex-col pt-4  rounded-t-[20px] bg-[#FEFEFE] fixed w-full camera-shots-gallery-container z-[999999999999] ${
          activeCameraGallery ? "top-16" : "top-[110vh]"
        } left-0`}
      >
        <div className="gallery-label pl-5 pr-5 flex-row items-center justify-start ">
          <CameraShotIcon />
          <span className="regular text-[13px] text-[#8D8D8D] ml-1">
            {translate("Buyers Camera")} 12 {translate("Shot")}
          </span>
          <ColorsInfo
            className="ml-1 cursor-pointer"
            onClick={() => {
              dispatch({
                type: "SHOW-INFO-MESSAGE",
                payload: {
                  showInfoMessage: true,
                  title: ` ${translate("Buyers Camera")} 12 ${translate(
                    "Shot"
                  )}`,
                  text: "According To The Opinions Of Our Fashion Team, The Appropriate Occasions For This Product Have Been Identified Based On Long Experience. We Provide An Opinion Only And Opinions May Differ From One Person To Another. So It Is Suitable For",
                  icon: "/svg/product/CameraShotIcon.svg",
                  value: ["Birthday", "Casual", "Business"],
                },
              });
            }}
          />
        </div>
        <span className="pl-12 regular text-[11px] text-[#C4C2C2]">
          {translateFunction(
            "These Shots Are Made By Users Who Have Already Purchased And Received The Product"
          )}
        </span>
        <div
          className={`flex-row flex-wrap w-full h-auto mt-1 container-gallery ${
            extended ? "pl-[10px] pr-[10px]" : "pl-5 pr-5"
          } max-h-[100vh] pb-[200px] overflow-auto`}
        >
          {images?.map((s, index) => {
            return (
              <GalleryItem
                key={index}
                onClick={() => setExtended(!extended)}
                extended={extended}
                name={"Yxxx Oxxx"}
                avatar={s}
                image={[s, s, s]}
                text={
                  "Amazing Product I Buy It And I Saw It Is Good Quality Regarding Price"
                }
                date={"12/2/2024"}
                likes={"110k"}
              />
            );
          })}
        </div>
      </div>
    </>
  );
}

